<script setup lang="ts">
import { SwitchRoot, SwitchThumb } from 'reka-ui'
import { presets, seededSequence } from '../../engine/presets'
import type { Op, TreeType } from '../../engine/types'
import { useSettingsStore } from '../../stores/settings'
const emit = defineEmits<{ preset: [ops: Op[], type?: TreeType]; operation: [op: Op]; share: []; clear: []; help: []; legend: []; text: [] }>()
const props = defineProps<{ value: string }>()
const settings = useSettingsStore().settings
const section = ref('examples')
const count = ref(15)
const seed = ref(42)
const key = computed(() => Number(props.value.split(/[,\s]/).find(Boolean)))
const views = [['showHeights', 'Mostrar alturas'], ['showNils', 'Mostrar folhas NIL'], ['showColors', 'Mostrar letras R/N'], ['showLevels', 'Mostrar níveis']] as const
const sections = [['examples', 'Exemplos'], ['traversals', 'Percursos'], ['queries', 'Consultas'], ['view', 'Visualização'], ['sequence', 'Sequência'], ['help', 'Ajuda']] as const
</script>
<template>
  <div class="lab-menu"><nav aria-label="Seções do menu"><button v-for="[id, label] in sections" :key="id" :class="{ active: section === id }" @click="section = id">{{ label }}</button></nav><div v-if="section === 'examples'" class="menu-presets"><button v-for="preset in presets" :key="preset.id" @click="emit('preset', preset.ops, preset.type)"><strong>{{ preset.title }}</strong><span>{{ preset.description }}</span><Icon name="lucide:arrow-right" /></button></div><div v-if="section === 'traversals'" class="menu-list"><p>Visite cada nó e acompanhe a saída.</p><button v-for="[order, label] in [['in', 'In-ordem · esquerda, raiz, direita'], ['pre', 'Pré-ordem · raiz, esquerda, direita'], ['post', 'Pós-ordem · esquerda, direita, raiz'], ['level', 'Por nível · fila de cima para baixo']] as const" :key="order" @click="emit('operation', { t: 'walk', order })"><Icon name="lucide:list-ordered" />{{ label }}</button></div><div v-if="section === 'queries'" class="menu-list"><button @click="emit('operation', { t: 'min' })">Mínimo<Icon name="lucide:chevrons-left" /></button><button @click="emit('operation', { t: 'max' })">Máximo<Icon name="lucide:chevrons-right" /></button><p>Sucessor e predecessor usam o primeiro valor do campo.</p><button :disabled="!Number.isInteger(key) || !value.trim()" @click="emit('operation', { t: 'succ', k: key })">Sucessor de {{ value.trim() ? key : 'k' }}<Icon name="lucide:arrow-right" /></button><button :disabled="!Number.isInteger(key) || !value.trim()" @click="emit('operation', { t: 'pred', k: key })">Predecessor de {{ value.trim() ? key : 'k' }}<Icon name="lucide:arrow-left" /></button></div><div v-if="section === 'view'" class="menu-list"><label v-for="[field, label] in views" :key="field" class="switch-row">{{ label }}<SwitchRoot v-model="settings[field]" :aria-label="label" class="setting-switch"><SwitchThumb class="switch-thumb" /></SwitchRoot></label><button @click="emit('text')">Ver como texto<Icon name="lucide:list" /></button></div><div v-if="section === 'sequence'" class="menu-list"><div class="seed-inputs"><label>Nós <input v-model.number="count" type="number" min="1" max="63"></label><label>Semente <input v-model.number="seed" type="number" min="0"></label></div><button @click="emit('preset', seededSequence(count, seed))">Gerar aleatória com semente<Icon name="lucide:shuffle" /></button><button @click="emit('share')">Copiar link ou compartilhar<Icon name="lucide:share-2" /></button><button @click="emit('clear')">Limpar sequência<Icon name="lucide:rotate-ccw" /></button></div><div v-if="section === 'help'" class="menu-list"><button @click="emit('help')">Como usar o laboratório<Icon name="lucide:help-circle" /></button><button @click="emit('legend')">Legenda dos destaques<Icon name="lucide:info" /></button><NuxtLink to="/ajustes">Abrir ajustes<Icon name="lucide:settings" /></NuxtLink></div></div>
</template>
